model.concert.stg_claim_edit_api__transa.raw_code:
{# Source Models #}
{%- set CLAIM_AUDIT_RECORD = source('claim_edit_api', 'claim_audit_deid_prod') -%}

{# Audit record "server" columns (refer to `macros/claim_edit_api/audit_record_utils.sql`) #}
{%- set SERVER_COLUMNS = [
	audit_col("workspace", "workspace"),
	audit_col("context", "context"),
	audit_col("editApiVersion", "edit_api_version"),
	audit_col("auditApiVersion", "audit_api_version"),
	audit_col("matchingModelId", "matching_model_id"),
	audit_col("matchingModelVersion", "matching_model_version"),
	audit_col("segmentVersion", "segment_version")
] -%}

{# Audit record "transaction" columns (transaction grain) #}
{%- set TRANSACTION_COLUMNS = [
	audit_col("id", "id"),
	audit_col("requestId", "request_id"),
	audit_col("traceId", "trace_id"),
	audit_col("customerId", "customer_id"),
	audit_col("configId", "config_id"),
	audit_col("configVersion", "config_version"),
	audit_col("editRequestTimestamp", "edit_request_timestamp", is_epoch=true),
	audit_col("editResponseTimestamp", "edit_response_timestamp", is_epoch=true),
	audit_col("auditReceivedTimestamp", "audit_received_timestamp", is_epoch=true),
	audit_col("auditSentTimestamp", "audit_sent_timestamp", is_epoch=true),
	audit_col("url", "url"),
] -%}

{# Audit record "claim" columns (claim grain) #}
{%- set CLAIM_COLUMNS = [
	audit_col("claimId", "claim_id"),
	audit_col("payerId", "payer_id"),
	audit_col("billingNPI", "billing_npi"),
	audit_col("billingEIN", "billing_ein"),
	audit_col("billingName", "billing_name"),
	audit_col("renderingNPI", "rendering_npi"),
	audit_col("renderingEIN", "rendering_ein"),
	audit_col("renderingName", "rendering_name"),
	audit_col("lineOfBusiness", "line_of_business"),
	audit_col("networkStatus", "network_status"),
	audit_col("placeOfService", "place_of_service"),
	audit_col("typeOfBill", "type_of_bill"),
	audit_col("admissionType", "admission_type"),
	audit_col("patientGender", "patient_gender"),
	audit_col("patientState", "patient_state"),
	audit_col("patientAgeBand", "patient_age_band", type="INT"),
	audit_col("icdVersion", "icd_version", type="INT"),
] -%}

{# Audit record "claim.lines[i]" columns (line grain) #}
{%- set LINE_COLUMNS = [
	audit_col("lineNumber", "line_number"),
	audit_col("dateOfService", "date_of_service", is_iso=true),
	audit_col("billed", "billed", type="REAL"),
	audit_col("allowed", "allowed", type="REAL"),
	audit_col("revenueCode", "revenue_code"),
	audit_col("status", "status"),
	audit_col("cptCode", "cpt_code"),
	audit_col("cptModifier1", "cpt_modifier_1"),
	audit_col("cptModifier2", "cpt_modifier_2"),
	audit_col("cptModifier3", "cpt_modifier_3"),
	audit_col("cptModifier4", "cpt_modifier_4"),
	audit_col("serviceUnits", "service_units", type="INT"),
	audit_col("hasAuthNumber", "has_auth_number", type="BOOLEAN"),
	audit_col("icdCode1", "icd_code_1"),
	audit_col("icdCode2", "icd_code_2"),
	audit_col("icdCode3", "icd_code_3"),
	audit_col("icdCode4", "icd_code_4"),
	audit_col("icdCode5", "icd_code_5"),
	audit_col("icdCode6", "icd_code_6"),
	audit_col("icdCode7", "icd_code_7"),
	audit_col("icdCode8", "icd_code_8"),
	audit_col("icdCode9", "icd_code_9"),
	audit_col("icdCode10", "icd_code_10"),
] -%}

{# Audit record "enrichments" column (claim grain) #}
{%- set CLAIM_ENRICHMENT_COLUMNS = [
	audit_col("lab", "lab_code"),
	audit_col("lob", "standard_line_of_business"),
	audit_col("pos", "standard_place_of_service"),
	audit_col("its", "standard_its_type"),
] -%}

{# Audit record "enrichments.segs" columns (segment grain) #}
{%- set SEGMENT_ENRICHMENT_COLUMNS = [
	audit_col("name", "segment_name"),
	audit_col("class", "segment_class"),
	audit_col("cat", "category_id"),
	audit_col("prob", "category_probability", type="REAL"),
] -%}

{# Audit record "enrichments.segs[i].lines[i]" columns (line grain) #}
{%- set LINE_ENRICHMENT_COLUMNS = [
	audit_col("targ", "line_target_count", type="INT"),
] -%}

{# Audit record "enrichments.segs[i].lines[i].edits[i]" columns (edit grain) #}
{%- set EDIT_ENRICHMENT_COLUMNS = [
	audit_col("id", "edit_id"),
	audit_col("ver", "edit_version", type="INT"),
	audit_col("rank", "edit_rank", type="INT"),
] -%}


WITH

-- Grab all audit records excluding errors
claim_record AS (
	SELECT * FROM {{ CLAIM_AUDIT_RECORD }}
	WHERE transaction."isError"::BOOLEAN = FALSE
),

-- Bulk majority of the claim record fields unnested to the transaction line grain
unnested_record__transaction_line AS (
	SELECT
		-- Server Data
		{%- for col in SERVER_COLUMNS %}
		  {{ audit_col_select('record.server', col) }},
		{% endfor -%}
		-- Transaction Data
		{%- for col in TRANSACTION_COLUMNS %}
		  {{ audit_col_select('record.transaction', col) }},
		{% endfor -%}
		-- Claim Grain Data
		{%- for col in CLAIM_COLUMNS %}
		  {{ audit_col_select('record.claim', col) }},
		{% endfor -%}
		-- Line Grain Data
		{%- for col in LINE_COLUMNS %}
		  {{ audit_col_select('line', col) }},
		{% endfor -%}
		-- Claim Grain Enrichments
		{%- call(col) for_delimited(CLAIM_ENRICHMENT_COLUMNS, ',') %}
		  {{ audit_col_select('record.enrichments', col) }}
		{% endcall -%}
	FROM
		claim_record        record,
		record.claim.lines  line
),

-- Enrichments section of the audit record unnested to the transaction edit grain
unnested_record__transaction_edit AS (
	SELECT
		-- Keys used for joining
		record.transaction.id::VARCHAR  AS id,
		line."num"::VARCHAR             AS line_number,
		-- Segment Grain Enrichments
		{%- for col in SEGMENT_ENRICHMENT_COLUMNS %}
		  {{ audit_col_select('segment', col) }},
		{% endfor -%}
		-- Line Grain Enrichments
		{%- for col in LINE_ENRICHMENT_COLUMNS %}
		  {{ audit_col_select('line', col) }},
		{% endfor -%}
		-- Edit Grain Enrichments
		{%- call(col) for_delimited(EDIT_ENRICHMENT_COLUMNS, ',') %}
		  {{ audit_col_select('edit', col) }}
		{% endcall -%}
	FROM
		claim_record             record,
		record.enrichments.segs  segment,
		segment.lines            line,
		line.edits               edit
),

final AS (
	SELECT
		-- All columns from the unnested transaction line grain
		{%- for col in (
			SERVER_COLUMNS +
			TRANSACTION_COLUMNS +
			CLAIM_COLUMNS +
			LINE_COLUMNS +
			CLAIM_ENRICHMENT_COLUMNS
		) %}
		  record.{{ col.alias }},
		{% endfor -%}
		-- All columns joined from the transaction edit grain enrichments
		{%- call(col) for_delimited((
			SEGMENT_ENRICHMENT_COLUMNS +
			LINE_ENRICHMENT_COLUMNS +
			EDIT_ENRICHMENT_COLUMNS
		), ',') %}
		  enrich.{{ col.alias }}
		{% endcall -%}
	FROM unnested_record__transaction_line record
	LEFT JOIN unnested_record__transaction_edit enrich ON
		record.id = enrich.id AND
		record.line_number = enrich.line_number
)

SELECT * FROM final

