model.concert.mart_claim_edit_api_claim.raw_code:
{{
  config(
    dist='claim_number',
    sort=['claim_number'],
    tags=['claim_edit_api_reporting'],
  )
}}

-- Dependencies
{% set FCT_CLAIM = ref('fct_claim_edit_api_claim') %}
{% set TOP_RANKED_EDIT = ref('claim_edit_api__line__top_ranked_edit') %}
{% set DIM_PROVIDER = ref('dim_provider') %}

-- Variables
{% set EDIT_SOURCES = var('ceapi_edit_sources') %}

WITH

claim_edit_metrics AS (
  SELECT
    claim_number,
    {% for edit_source in EDIT_SOURCES %}
      {% set alias = edit_source.name ~ '_edit' %}
      SUM({{ alias }}_edited_billed_amount)             AS {{ alias }}_savings{% if not loop.last %},{% endif %}
    {% endfor %}
  FROM {{ TOP_RANKED_EDIT }}
  GROUP BY 1
),

final AS (
  SELECT
    claim.*,
    billing_provider.provider_ein                       as billing_provider_ein,
    billing_provider.lab_code                           as billing_provider_lab_code,
    billing_provider.lab_name                           as billing_provider_lab_name,
    rendering_provider.provider_ein                     as service_provider_ein,
    rendering_provider.provider_npi                     as service_provider_npi,
    rendering_provider.lab_name                         as service_provider_lab_name,
    rendering_provider.lab_code                         as service_provider_lab_code,
    rendering_provider.provider_name                    as service_provider_name,
    {% for edit_source in EDIT_SOURCES %}
      {% set alias = edit_source.name ~ '_edit' %}
      edit.{{ alias }}_savings{% if not loop.last %},{% endif %}
    {% endfor %}
  FROM {{ FCT_CLAIM }} claim
  LEFT JOIN claim_edit_metrics edit ON
    claim.claim_number = edit.claim_number
  LEFT JOIN {{ DIM_PROVIDER }} billing_provider ON
    claim.billing_provider_key = billing_provider.provider_key
  LEFT JOIN {{ DIM_PROVIDER }} rendering_provider ON
    claim.service_provider_key = rendering_provider.provider_key
)

SELECT * FROM final

model.concert.mart_claim_edit_api_segmen.raw_code:
{{
  config(
    dist='claim_number',
    sort=['claim_number', 'segment_key'],
    tags=['claim_edit_api_reporting'],
  )
}}

-- Dependencies
{% set FCT_SEGMENT = ref('fct_claim_edit_api_segment') %}
{% set TOP_RANKED_EDIT = ref('claim_edit_api__line__top_ranked_edit') %}
{% set DIM_SUBSCRIBER = ref('dim_claim_edit_subscriber') %}
{% set DIM_PROVIDER = ref('dim_provider') %}
{% set DIM_CATEGORY = ref('dim_category') %}

-- Variabes
{% set EDIT_SOURCES = var('ceapi_edit_sources') %}

WITH

segment_edit_metrics AS (
  SELECT
    segment_key,

    {% for edit_source in EDIT_SOURCES %}
      {% set alias = edit_source.name ~ '_edit' %}
      SUM({{ alias }}_edited_billed_amount)              AS {{ alias }}_savings{% if not loop.last %},{% endif %}
    {% endfor %}
  FROM {{ TOP_RANKED_EDIT }}
  GROUP BY 1
),

final AS (
  SELECT
    segment.*,
    billing_provider.provider_ein                       as billing_provider_ein,
    billing_provider.lab_code                           as billing_provider_lab_code,
    billing_provider.lab_name                           as billing_provider_lab_name,
    rendering_provider.provider_ein                     as service_provider_ein,
    rendering_provider.provider_npi                     as service_provider_npi,
    rendering_provider.lab_name                         as service_provider_lab_name,
    rendering_provider.lab_code                         as service_provider_lab_code,
    rendering_provider.provider_name                    as service_provider_name,
    category.category_name,
    category.domain_name,
    category.area_name,
    subscriber.claim_edit_subscriber_name,
    {% for edit_source in EDIT_SOURCES %}
      {% set alias = edit_source.name ~ '_edit' %}
      edit.{{ alias }}_savings{% if not loop.last %},{% endif %}
    {% endfor %}
  FROM {{ FCT_SEGMENT }} segment
  LEFT JOIN segment_edit_metrics edit ON
    segment.segment_key = edit.segment_key
  LEFT JOIN {{ DIM_PROVIDER }} billing_provider ON
    segment.billing_provider_key = billing_provider.provider_key
  LEFT JOIN {{ DIM_PROVIDER }} rendering_provider ON
    segment.service_provider_key = rendering_provider.provider_key
  LEFT JOIN {{ DIM_SUBSCRIBER }} subscriber ON
    segment.claim_edit_subscriber_code = subscriber.claim_edit_subscriber_code
  LEFT JOIN {{ DIM_CATEGORY }} category ON
    segment.category_id = category.category_id
)

SELECT * FROM final

