model.concert.dim_procedure_code_scopes.raw_code:
{{
    config(
        dist='all',
        sort=['code'], 
    )
}}

{% set default_row_keys = var('default_row_keys') %}

with 

codes as (
    select * from {{ ref('stg_concert_db__cpt_code_references')}}
), 

final_code as (
    select code, 
    case
        when program_scope = 'Genetics' then 'genetic' else 'N/A'
    end as is_genetic, 
    case 
        when program_scope = 'Infectious Disease' then 'infectious_disease' else 'N/A'
    end as is_infectious_disease, 
    case 
        when program_scope = 'General Lab' then 'general_lab' else 'N/A'
    end as is_general_lab,
    case
        when program_scope = 'Imaging' then 'imaging' else 'N/A'
    end as is_imaging,
    case
        when program_scope = 'Out of Scope' then 'out_of_scope' else 'N/A'
    end as is_out_of_scope,
    description_long,
    description_medium, 
    test_name, 
    lab_name, 
    mol_path_code, 
    mol_path_tier_1_code, 
    mol_path_tier_2_code, 
    gsp_code, 
    cat_1_maaa_code,
    admin_maaa_code, 
    ihc_code, 
    pla_code, 
    allergy_code,
    effective_start_date, 
    effective_end_date
    from codes
), 

default_code as (
    {% call(key) for_delimited(default_row_keys, 'union all')%}
    select {{ default_procedure_code_types_columns(key) }}
    {% endcall %}
), 

final as (
    select * from final_code
    union all 
    select * from default_code
)

select * from final

