model.concert.bdg_claim_edit_criteria.raw_code:
{{
  config(
    dist='all',
    sort=['criteria_id'],
  )
}}

with 

parent AS (
  SELECT * FROM {{ ref('stg_concert_db__parent_criteria') }}
),

criteria as (
  select * from {{ ref('stg_concert_db__policy_criteria')}}
),

claim_edit as (
  select * from {{ ref('stg_concert_db__claim_edits')}}
),

final as (
  select
    claim_edit.claim_edit_key AS claim_edit_key,
    claim_edit.id             AS claim_edit_id,
    claim_edit.version        AS claim_edit_version,
    criteria.id               AS criteria_id,
    row_number() over (
      partition by
        claim_edit.claim_edit_key,
        criteria.code
      order by
        {{ semver_at_idx('criteria.version', 1) }} desc,
        {{ semver_at_idx('criteria.version', 2) }} desc
    ) as criteria_rank
  from parent
  inner join criteria
    on parent.code = criteria.code
  inner join claim_edit
  on (
    {{ compare_semver('criteria.version', 'claim_edit.criteria_version_start') }} in (1, 0) 
    and (
      claim_edit.criteria_version_end is null
        or {{ compare_semver('criteria.version', 'claim_edit.criteria_version_end') }} in (-1, 0) 
    )
    and parent.code = claim_edit.parent_criteria_code
    and criteria.code = claim_edit.parent_criteria_code
  )
)

select * from final

model.concert.fct_claim_edit_api_summary.raw_code:
{{
  config(
    sort=['date_of_transaction'],
    tags=['claim_edit_api_reporting'],
  )
}}

with

summary as (
  select * from {{ ref('stg_orders_db__claim_edit_api_summary_by_edits') }}
),

customer as (
  select * from {{ ref('dim_customer') }}
),

claim_edit_subscriber as (
  select * from {{ ref('dim_claim_edit_subscriber') }}
),

claim_edit as (
  select * from {{ ref('dim_claim_edit') }}
),

final as (
  select
    -- Dimensions
    {{
      dbt_utils.generate_surrogate_key([
        "coalesce(claim_edit.claim_edit_id, 'Unknown')",
        "coalesce(claim_edit.claim_edit_version, 1)",
      ])
    }} as claim_edit_key,
    coalesce(
      summary.customer_code,
      'Unspecified'
    ) as customer_code,
    coalesce(
      claim_edit_subscriber.claim_edit_subscriber_code,
      summary.customer_code,
      'Unknown'
    ) as claim_edit_subscriber_code,
    coalesce(summary.payer_id, 'Unspecified') as payer_id,
    summary.requested_at as date_of_transaction,
    -- Facts
    summary.claims as claim_volume,
    summary.claims_edited as edited_claim_volume,
    summary.lines as line_volume,
    summary.lines_edited as edited_line_volume,
    summary.billed as billed_amount,
    summary.billed_edited as edited_billed_amount
  from summary
  left join customer
    on summary.customer_code = customer.customer_code
  left join claim_edit_subscriber
    on customer.customer_code = claim_edit_subscriber.claim_edit_subscriber_code
  -- Optimized join using claim edit key dist key
  left join claim_edit on
    {{
      dbt_utils.generate_surrogate_key([
        "coalesce(summary.edit_short_code, 'Unspecified')",
        "coalesce(summary.edit_version, 1)",
      ])
    }} = claim_edit.claim_edit_key
)

select * from final

model.concert.bdg_claim_edit_api_line_ed.raw_code:
{{
  config(
    dist='claim_number',
    sort=['claim_number'],
  )
}}

{% set EDIT_SOURCES = [
  { 'name': 'AUDIT', 'model': 'stg_spectrum__claim_audit_lines', 'exclude_trace': true },
  { 'name': 'UDF_CONCERT', 'model': 'claim_edit_api_line_edit__unnested' },
  { 'name': 'UDF_CONCERT_QA', 'model': 'claim_edit_api_line_edit__qa_unnested' },
  { 'name': 'UDF_CUSTOMER', 'model': 'claim_edit_api_line_edit__customer__unnested' },
  { 'name': 'UDF_CUSTOMER_QA', 'model': 'claim_edit_api_line_edit__customer__qa_unnested' },
] %}

{% set DIM_CLAIM_EDIT = ref('dim_claim_edit') %}

with

line_edit as (
  {% call(edit_source) for_delimited(EDIT_SOURCES, 'union all') %}
    (
      select
        claim_number,
        request_id,
        segment_key,
        claim_line_number,
        edit_short_code,
        edit_version,
        edit_rank,

        {% if edit_source.exclude_trace %}
          'Not Applicable'        as edit_trace,
        {% else %}
           any_value(
            coalesce(edit_trace, 'Not Applicable')
          )                       as edit_trace,
        {% endif %}

        '{{ edit_source.name }}'  as edit_source
      from {{ ref(edit_source.model) }}
      group by 1, 2, 3, 4, 5, 6, 7
    )
  {% endcall %}
),

final as (
  select
    line_edit.claim_number,
    line_edit.segment_key,
    line_edit.claim_line_number,
    line_edit.request_id,
    {{
      dbt_utils.generate_surrogate_key([
        'line_edit.claim_number',
        'line_edit.claim_line_number',
        'line_edit.request_id'
      ])
    }}                                as claim_edit_api_line_key,
    {{
      dbt_utils.generate_surrogate_key([
        "coalesce(claim_edit.claim_edit_id, 'Unknown')",
        "coalesce(claim_edit.claim_edit_version, 1)",
      ])
    }} as claim_edit_key,
    line_edit.edit_source             as edit_source,
    coalesce(line_edit.edit_rank, 1)  as edit_rank,
    edit_trace,
    md5(edit_trace)                   as edit_trace_hash
  from line_edit
  left join {{ DIM_CLAIM_EDIT }} claim_edit
    on coalesce(line_edit.edit_short_code, 'Unspecified') = claim_edit.claim_edit_short_code
      and coalesce(line_edit.edit_version, 1) = claim_edit.claim_edit_version
)

select * from final

