model.concert.dim_provider.raw_code:
{{
  config(
    dist='all',
    sort=['provider_key'],
    tags=['ppp_dependency']
  )
}}

{% set default_row_keys = var('default_row_keys') %}
{% set post_pay_provider_types = ['billing', 'service'] %}
{% set claim_edit_api_provider_types = ['billing', 'rendering'] %}

-- Model Dependencies
{% set STG_CLAIM_EDIT_API_LINE = ref('stg_spectrum__claim_audit_lines') %}
{% set DIM_LAB_SYNONYM = ref('dim_lab_synonym') %}
{% set DIM_LAB = ref('dim_lab') %}

-- Provider Sources
{% set provider_sources = ({
  'post_pay': {
    'provider_prefixes': ['billing_provider', 'service_provider']
  },
  'claim_edit_api': {
    'provider_prefixes': ['billing', 'rendering']
  },
}) %}

WITH 

lines AS (
  SELECT * FROM {{ source('post_pay_sources', 'post_pay_payers_claims_lines') }}
),

{% for source_name, provider_source in provider_sources.items() %}
  unique_{{ source_name }}_provider as (
    {% call(provider_prefix) for_delimited(provider_source.provider_prefixes, 'union') %}  
      SELECT DISTINCT
        {{ provider_prefix }}_ein  AS provider_ein,
        {{ provider_prefix }}_npi  AS provider_npi,
        {{ provider_prefix }}_name AS provider_name
      {% if source_name == 'claim_edit_api' %}
        FROM {{ STG_CLAIM_EDIT_API_LINE }} 
      {% elif source_name == 'post_pay' %}
        FROM LINES 
      {% endif %}
    {% endcall %}
  ),
{% endfor %}

unique_provider as (
  {% call(item) for_delimited(provider_sources.items(), 'union') %}
    {% set source_name = item[0] %}
    select * from unique_{{ source_name }}_provider
  {% endcall %}
),

provider_lab as (
  select
    {{
      dbt_utils.generate_surrogate_key([
        'provider_ein',
        'provider_npi',
        'provider_name'
      ])
    }} as provider_key,
    provider_ein,
    provider_npi,
    provider_name,
    coalesce(
      ein_synonym.lab_code,
      npi_synonym.lab_code,
      name_synonym.lab_code,
      'Unknown'
    ) as lab_code
  from unique_provider
  left join {{ DIM_LAB_SYNONYM }} ein_synonym
    on ein_synonym.synonym_type = 'EIN'
      and unique_provider.provider_ein = ein_synonym.lab_synonym
  left join {{ DIM_LAB_SYNONYM }} npi_synonym
    on ein_synonym.lab_code is null
      and npi_synonym.synonym_type = 'NPI'
      and unique_provider.provider_npi = npi_synonym.lab_synonym
  left join {{ DIM_LAB_SYNONYM }} name_synonym
    on ein_synonym.lab_code is null
      and npi_synonym.lab_code is null
      and name_synonym.synonym_type = 'NAME'
      and unique_provider.provider_name = name_synonym.lab_synonym
),

initial_provider as (
  select
    provider_lab.provider_key,
    provider_lab.provider_ein,
    provider_lab.provider_npi,
    provider_lab.provider_name,
    lab.lab_code,
    lab.lab_name,
    lab.lab_url,
    lab.lab_status,
    row_number() over(
      partition by
        provider_lab.provider_key
      order by
        lab.lab_status DESC
    ) as status_order
  from provider_lab
  inner join {{ DIM_LAB }} lab
    on provider_lab.lab_code = lab.lab_code
),

final_provider as (
  select
    provider_key,
    coalesce(provider_ein, 'Unspecifed')   as provider_ein,
    coalesce(provider_npi, 'Unspecified')  as provider_npi,
    coalesce(provider_name, 'Unspecified') as provider_name,
    lab_code,
    lab_name,
    lab_url,
    lab_status
  from initial_provider
  where status_order = 1
),

default_provider as (
  {% call(key) for_delimited(default_row_keys|reject('eq', 'Unspecified'), 'union all') %}
    select {{ default_provider_columns(key) }}
  {% endcall %}
),

final as (
  select * from final_provider
  union
  select * from default_provider
)

select * from final

model.concert.dim_lab.raw_code:
{{
  config(
    dist='all',
    sort=['lab_code'],
  )
}}

{% set default_row_keys = var('default_row_keys') %}

with

