),

diff as (
  select * from {{ ref('stg_concert_db__diffs') }}
),

ordered_diffs_by_lab as (
  select
    *,
    row_number() over (
      partition by lab_code
      order by date_imported desc nulls last
    ) as row_number
  from diff
),

last_imported_diff_by_lab as (
  select *
  from ordered_diffs_by_lab
  where row_number = 1
    and date_imported is not null
),

final_lab as (
  select
    lab.code as lab_code,
    coalesce(lab.name, 'Unspecified') as lab_name,
    coalesce(lab.url, 'Unspecified') as lab_url,
    coalesce(
      nullif({{ safe_json_extract('lab.internal', ['status']) }}, ''),
      'Unspecified'
    ) as lab_status,
    {{ safe_json_extract('lab.internal', ['tier']) }}::int as lab_tier,
    {{ safe_json_extract('lab.internal', ['lastAutomatedDiff']) }}::timestamp as last_automated_diff_date,
    last_imported_diff_by_lab.date_imported as last_imported_diff_date
  from lab
  left join last_imported_diff_by_lab
    on lab.code = last_imported_diff_by_lab.lab_code
),

default_lab as (
  {% call(key) for_delimited(default_row_keys, 'union all') %}
    select {{ default_lab_columns(key) }}
  {% endcall %}
),

final as (
  select * from final_lab
