    dist='all',
    sort=['criteria_id'],
    tags=['ppp_dependency']
  )
}}

{% set default_row_keys = var('default_row_keys') %}

with

criteria as (
  select * from {{ ref('stg_concert_db__policy_criteria') }}
),

policy as (
  select * from {{ ref('dim_policy') }}
),

policy_policy_criteria as (
  select * from {{ ref('bdg_policy_policy_criteria') }}
),

final_criteria as (
  select
    criteria.id as criteria_id,
    criteria.code as criteria_code,
    criteria.parent_policy_code as criteria_parent_policy_code,
    (
      regexp_replace(criteria.version, '\.[^.]*$', '') 
    ) as criteria_version,
    (
      regexp_replace(criteria.policy_version_start, '\.[^.]*$', '') 
    ) as criteria_policy_version_start,
    (
      regexp_replace(coalesce(criteria.policy_version_end, 'Unspecified'), '\.[^.]*$', '') 
    ) as criteria_policy_version_end,
    coalesce(nullif(criteria.name, ''), 'Unspecified') as criteria_name,
    criteria.status as criteria_status,
    policy.policy_id,
    policy.content_type,
    policy.policy_code,
    policy.policy_version,
    policy.policy_name,
    policy.policy_url,
    policy.policy_overview,
    policy.policy_type,
    policy.policy_group,
    policy.policy_content_state,
    policy.policy_last_review_date,
    policy.policy_next_review_date
  from criteria
  left join policy_policy_criteria
    on criteria.id = policy_policy_criteria.criteria_id
  left join policy
    on policy_policy_criteria.policy_id = policy.policy_id
),

default_criteria as (
  {% call(key) for_delimited(default_row_keys, 'union all') %}
    select {{ default_criteria_columns(key) }}
  {% endcall %}
),

final as (
  select * from final_criteria
  union all
  select * from default_criteria
)

select * from final

