-- List of line sources with their respective model references
{% set LINE_SOURCES = [
  {
    'name': 'POST_PAY',
    'ref': ref('ext_int__post_pay__line'),
  },
  {
    'name': 'CLAIM_EDIT_API',
    'ref': ref('ext_int__claim_edit_api__line'),
  },
] %}

-- Columns shared between both data sources
{% set SHARED_COLUMNS = [
  'claim_number',
  'lines_on_claim',
  'min_date_of_service',
  'segment_class',
  'segment_name',
  'target_count',
  'billing_ein',
  'billing_npi',
  'billing_name',
  'billing_lab_code',
  'service_ein',
  'service_npi',
  'service_name',
  'service_lab_code',
  'line_of_business',
  'network_status',
  'place_of_service',
  'patient_gender',
  'patient_state',
  'patient_age',
  'line_number',
  'date_of_service',
  'billed',
  'allowed',
  'status',
  'cpt_code',
  'service_units',
  'cpt_modifier_1',
  'cpt_modifier_2',
  'cpt_modifier_3',
  'cpt_modifier_4',
  'icd_code_1',
  'icd_code_2',
  'icd_code_3',
  'icd_code_4',
  'icd_code_5',
  'icd_code_6',
  'icd_code_7',
  'icd_code_8',
  'icd_code_9',
  'icd_code_10',
  'category_id',
  'category_confidence',
  'claim_edit_key',
  'edit_trace_hash',
  'procedure_for_api_whitelisting',
  'procedure_for_api_segmentation',
] %}

-- Custom Column Definitions (Array of Tuples{column_name, default_value})
{% set POST_PAY_CUSTOM_COLUMNS = [
  { 'name': 'payer_code', 'default': 'null::varchar' },
  { 'name': 'next_segment_class', 'default': 'null::varchar' },
  { 'name': 'next_segment_name', 'default': 'null::varchar' },
  { 'name': 'next_target_count', 'default': 'null::int' },
] %}
{% set CLAIM_EDIT_API_CUSTOM_COLUMNS = [] %} -- Empty for now (but can be filled in)


with

-- Gather source data and resolve shared and custom columns
{% for line_source in LINE_SOURCES %}

  {{ line_source.name }}_line as (
    select
      -- Tag the source
      '{{ line_source.name }}' as line_source,
      -- Select shared columns
      {% call(column_name) for_delimited(SHARED_COLUMNS, ',') %}
        {{ column_name }}
      {% endcall %}
      -- Custom Post Pay Columns
      {% if (POST_PAY_CUSTOM_COLUMNS|length) > 0 %}
        , -- Intentional comma :D
        {% call(column) for_delimited(POST_PAY_CUSTOM_COLUMNS, ',') %}
          {% if line_source.name == 'POST_PAY' %}
            {{ column.name }}
          {% else %}
            {{ column.default }} as {{ column.name }}
          {% endif %}
        {% endcall %}
      {% endif %}
      -- Custom Claim Edit Columns
      {% if (CLAIM_EDIT_API_CUSTOM_COLUMNS|length) > 0 %}
        , -- Intentional comma ;)
        {% call(column) for_delimited(CLAIM_EDIT_API_CUSTOM_COLUMNS, ',') %}
          {% if line_source.name == 'CLAIM_EDIT_API' %}
            {{ column.name }}
          {% else %}
            {{ column.default }} as {{ column.name }}
          {% endif %}
        {% endcall %}
      {% endif %}
    from {{ line_source.ref }}
  ),

{% endfor %}

-- Join line sources together into one big ol' dataset
final as (
  {% call(line_source) for_delimited(LINE_SOURCES, 'UNION ALL') %}
    select * from {{ line_source.name }}_line
  {% endcall %}
)

select * from final

