claim_edit_api_line as (
  select * from {{ ref('base_claim_edit_api_line') }}
),

flattened_icd as (
  {% call(i) for_delimited(range(1, 11), 'union') %}
    select
      claim_number,

      diagnosis_code_{{ i }} as diagnosis_code
    from claim_edit_api_line
  {% endcall %}
),
line_diagnosis as (
  select
    flattened_icd.claim_number,
    flattened_icd.diagnosis_code,
    COALESCE(diagnosis.diagnosis_description, 'Unknown') AS diagnosis_description
  from flattened_icd
  left join {{ DIM_DIAGNOSIS }} diagnosis
    on flattened_icd.diagnosis_code = diagnosis.diagnosis_code
),

final as (
  select
    claim_number,
    coalesce(
      nullif(
        listagg(
          nullif(diagnosis_code, 'Unspecified'),
          ' '
        )
        within group (order by diagnosis_code),
        ''
      ),
      'Unspecified'
    ) as diagnosis_signature,
    listagg(
      nullif(diagnosis_code, 'Unspecified') || ': ' || diagnosis_description,
      ' | '
    ) within group (
      order by diagnosis_code
    ) as diagnosis_descriptions
  from line_diagnosis
  group by 1
