model.concert.procedure_crosswalk__unnes.raw_code:
{{
  config(
    dist='all',
    sort=['procedure_code'],
  )
}}

with

seed_code_crosswalk as (
  select * from {{ ref('stg_code_crosswalk') }}
),

numbers as (
  {{ dbt_utils.generate_series(upper_bound=10) }}
),

unnested as (
  select
    seed_code_crosswalk.code as procedure_code,
    case
      when comp_code like '%+%'
        then '+'
      else '|'
    end as operator,
    nullif(
      split_part(
        seed_code_crosswalk.comp_code,
        operator,
        numbers.generated_number::int
      ),
      ''
    ) as comparable_procedure_code
  from seed_code_crosswalk
  cross join numbers
  where seed_code_crosswalk.comp_code is not null
    and comparable_procedure_code is not null
),

final as (
  select
    procedure_code,
    case
      when operator = '+'
        then 'SUM'
      else 'ANY'
    end as operator,
    comparable_procedure_code
  from unnested
)

select * from final

model.concert.claim_edit_api__segment__g.raw_code:
{{
  config(
    dist='claim_number',
    sort=['claim_number'],
  )
}}

{% set provider_types = var('provider_types') %}

with

claim_edit_api_line as (
  select * from {{ ref('base_claim_edit_api_line') }}
  where latest_claim_indicator = 1
),

claim_edit_api_claim as (
  select
    claim_number,

    ANY_VALUE(request_id)                             as request_id,
    ANY_VALUE(claim_edit_subscriber_code)             as claim_edit_subscriber_code,
    ANY_VALUE(payer_id)                               as payer_id,
    ANY_VALUE(line_of_business)                       as line_of_business,
    ANY_VALUE(network_status)                         as network_status,
    ANY_VALUE(member_sex)                             as member_sex,
    ANY_VALUE(billing_provider_key)                   as billing_provider_key,
    ANY_VALUE(service_provider_key)                   as service_provider_key
  from claim_edit_api_line
  group by 1
),

category as (
  select * from {{ ref('dim_category') }}
),

provider AS (
  SELECT
    provider_key,
    provider_ein,
    provider_npi
  FROM {{ ref('dim_provider') }}
),

-- Aggregate claim attributes
claim_agg as (
  select
    claim_number,
    {{ line_attr("procedure_code") }}                         AS all_procedure_code,
    {% for i in range(1, 5) %}
      {% set mod = 'procedure_modifier_' ~ i %}
      {{
        line_attr(
          "case when btrim(" ~ mod ~ ") ~ '^[0-9A-Z]{2}$'" ~
            " then " ~ mod ~
            " else null::varchar " ~
          "end"
        )
      }}                                                      AS all_procedure_modifier_{{ i }},
    {% endfor %}
    {% call(i) for_delimited(range(1, 11), ',') %}
      {% set code = 'diagnosis_code_' ~ i %}
      {{
        line_attr(
          "case when " ~ code ~ " = 'Unspecified'" ~
            " then null::varchar" ~
            " else " ~ code ~
          " end"
        )
      }}                                                      AS all_icd_code_{{ i }}
    {% endcall %}
  from claim_edit_api_line
  group by 1
),

-- Aggregate lines to the segment level
segment as (
  select
    segment_key,

    ANY_VALUE(claim_number)                                   AS claim_number,
    ANY_VALUE(member_age_band)                                AS patient_age_band,
    ANY_VALUE(member_state_code)                              AS patient_state_code,
    ANY_VALUE(billing_provider_lab_code)                      AS billing_provider_lab_code,
    ANY_VALUE(service_provider_lab_code)                      AS service_provider_lab_code,
    ANY_VALUE(standard_place_of_service)                      AS standard_place_of_service,
    ANY_VALUE(category_id)                                    AS category_id,
    {{ line_attr("coalesce(billed_amount, 0)") }}             AS all_billed_amount,
    {{ line_attr("TO_CHAR(date_of_service, 'YYYY-MM-DD')") }} AS all_date_of_service,
    {{ line_attr("service_units") }}                          AS all_service_units
  from claim_edit_api_line
  group by 1
),

final as (
  select
    segment.claim_number                                      AS claim_number,
    claim.request_id                                          AS request_id,
    segment.segment_key                                       AS segment_key,

    claim.payer_id                                            AS payer_id,
    claim.claim_edit_subscriber_code                          AS claim_edit_subscriber_code,
    segment.patient_age_band                                  AS patient_age_band,
    case when segment.patient_state_code ~ '[A-Z]{2}'
      then segment.patient_state_code
      else 'XX'
    end                                                       AS patient_state_code,
    case claim.member_sex
      when 'Male' then 'M'
      when 'Female' then 'F'
      else 'U'
    end                                                       AS patient_gender,
    {% for provider_type in provider_types %}
      {% set label = 'rendering' if provider_type == 'service' else provider_type %}
        {{ provider_type }}_provider.provider_ein    AS {{ label }}_provider_ein,
        {{ provider_type }}_provider.provider_npi    AS {{ label }}_provider_npi,
    {% endfor %}
    coalesce(
      segment.service_provider_lab_code,
      nullif(segment.billing_provider_lab_code, 'Unknown')
    )                                        AS service_provider_lab_code,
    segment.standard_place_of_service        AS standard_place_of_service,
    claim.line_of_business                   AS line_of_business,
    case when (
      claim.network_status = 'I' or
      claim.network_status = 'O'
    )
      then claim.network_status
      else 'U'
    end                                      AS network_status,
    category.category_id                     AS category_id,
    segment.all_billed_amount                AS all_billed_amount,
    segment.all_date_of_service              AS all_date_of_service,
    claim_agg.all_procedure_code             AS all_procedure_code,
    {% for i in range(1,5) %}
      claim_agg.all_procedure_modifier_{{ i }} AS all_procedure_modifier_{{ i }},
    {% endfor %}
    segment.all_service_units                AS all_service_units,
    {% call(i) for_delimited(range(1,11), ',') %}
      claim_agg.all_icd_code_{{ i }}         AS all_icd_code_{{ i }}
    {% endcall %}
  from segment
  inner join category
    on segment.category_id = category.category_id
  inner join claim_edit_api_claim claim
    on segment.claim_number = claim.claim_number
  inner join claim_agg on
    segment.claim_number = claim_agg.claim_number
  {% for provider_type in provider_types %}
      inner join provider {{ provider_type }}_provider
        on claim.{{ provider_type }}_provider_key = {{ provider_type }}_provider.provider_key
  {% endfor %}
)

select * from final

model.concert.claim_edit_qa__editing__in.raw_code:
{{
  config(
    dist='claim_number',
    sort=['claim_number'],
    tags=['qa_claim_edits']
  )
}}

-- Model Dependencies
{% set BDG_CLAIM_SEGMENT_LINE = source('post_pay_staging', 'bdg_claim_segment_line') %}
{% set PRE_EDITING_FORMATTING = source('post_pay_staging', 'pre_editing_formatting') %}
{% set POST_PAY_LINE = source('post_pay_sources', 'post_pay_payers_claims_lines') %}


-- local variables
{% set date_floor = "dateadd(month, -12, CURRENT_DATE)" %}
{% set date_ceiling = "dateadd(month, -6, CURRENT_DATE)" %}

-- segments for editing
SELECT
  DISTINCT
  B.claim_number,
  A.segment_key
FROM {{ PRE_EDITING_FORMATTING }} A
JOIN {{ BDG_CLAIM_SEGMENT_LINE }} B
  ON A.segment_key = B.segment_key
JOIN {{ POST_PAY_LINE }} C
  ON B.post_pay_line_key = C.post_pay_line_key
  AND C.date_of_service BETWEEN {{ date_floor }} AND {{ date_ceiling }}

model.concert.claim_edit_qa__edited.raw_code:
{{
  config(
    dist='claim_number',
    sort=['claim_number'],
    tags=['qa_claim_edits']
  )
}}

-- Model Dependencies
{% set CLAIM_EDIT_QA_SEGMENTS = ref('claim_edit_qa__editing__input') %}
{% set PRE_EDITING_FORMATTING = source('post_pay_staging', 'pre_editing_formatting') %}

WITH

edited AS (
  SELECT
      segments_for_editing.claim_number,
      A.segment_key,

      json_parse(
        edit_claim(
            -- Configuration JSON string
            {{ to_json_string({
              "toggle": { "literal": "post-pay" },
              "customerCode": { "literal": "CONCERT" },
              "qaEdit": { "literal": "true", "quoted": false },
            }) }},
            -- Patient JSON string
            {{ to_json_string({
              "ageBand": { "sql": "A.patient_age_band", "quoted": false },
              "stateCode": { "sql": "A.patient_state_code" },
              "gender": { "sql": "A.patient_gender" },
            }) }},
            -- Provider JSON string
            {{ to_json_string({
              "billingEIN": { "sql": "A.billing_provider_ein" },
              "billingNPI": { "sql": "A.billing_provider_npi" },
              "renderingEIN": { "sql": "A.rendering_provider_ein" },
              "renderingNPI": { "sql": "A.rendering_provider_npi" },
            }) }},
            A.line_of_business,
            A.network_status,
            A.standard_place_of_service,
            A.category_id,
            A.all_billed_amount,
            A.all_billed_amount,
            A.all_date_of_service,
            A.all_procedure_code,
            {% for i in range(1,5) %}
                A.all_procedure_modifier_{{ i }},
            {% endfor %}
            A.all_service_units,
            {% call(i) for_delimited(range(1,11), ',') %}
                A.all_icd_code_{{ i }}
            {% endcall %}
        )
      ) as all_line_edits
  FROM {{ PRE_EDITING_FORMATTING }} A
  INNER JOIN {{ CLAIM_EDIT_QA_SEGMENTS }} segments_for_editing
    ON A.segment_key = segments_for_editing.segment_key
)

SELECT
    claim_number,
    segment_key,
    all_line_edits
FROM edited

macro.concert.get_drop_query.macro_sql:
{% macro get_drop_query() %}

  -- Modified to work with Redshift: https://discourse.getdbt.com/t/faq-cleaning-up-removed-models-from-your-production-schema/113/3

  {% set NON_SOURCE_SCHEMAS = ['dw_staging', 'dw_common', 'dw_marts'] %}

  {% set WHERE_SCHEMA_IS %}
    WHERE
      {% for schema in NON_SOURCE_SCHEMAS %}
        schema_name = '{{ schema }}' {% if not loop.last %}OR{% endif %}
      {% endfor %}
  {% endset %}

  {% call statement('get_outdated_models', fetch_result=True) %}
    SELECT
      current.schema_name,
      current.ref_name,
      current.ref_type
    FROM (
      SELECT
        schemaname AS schema_name, 
        tablename  AS ref_name, 
        'table'    AS ref_type
      FROM pg_catalog.pg_tables pt 
      {{ WHERE_SCHEMA_IS }}
      UNION ALL
      SELECT
        schemaname AS schema_name, 
        viewname   AS ref_name, 
        'view'     AS ref_type
      FROM pg_catalog.pg_views
      {{ WHERE_SCHEMA_IS }}
    ) as current
    LEFT JOIN (
      {%- for node in graph.nodes.values() | selectattr("resource_type", "equalto", "model") | list
                    + graph.nodes.values() | selectattr("resource_type", "equalto", "seed")  | list %} 
        SELECT '{{node.schema}}', '{{node.name}}' {% if not loop.last %}UNION ALL{% endif %}
      {%- endfor %}
    ) AS desired (schema_name, ref_name)
      ON desired.schema_name = current.schema_name
