macro.concert.post_pay_payment_status__s.macro_sql:
{% macro post_pay_payment_status__segment__grouped(payer_code) %}
    -- Vars
    {% set payment_statuses = [
        { 'name': 'paid', 'flag': 'P' },
        { 'name': 'denied', 'flag': 'D' },
    ] %}

    -- Model Dependencies
    {% set POST_PAY_LINES = source('post_pay_sources', 'post_pay_payers_claims_lines') %}
    {% set BDG_CLAIM_SEGMENT_LINE = source('post_pay_staging', 'bdg_claim_segment_line') %}
    {% set destination_table = source('dw_common', 'post_pay_payment_status__segment__grouped') %}

    {% set query %}
        DELETE FROM {{ destination_table }}
        WHERE payer_code = '{{ payer_code }}';

        INSERT INTO {{ destination_table }}
        ( {{ generate_column_list_insert(post_pay_payment_status__segment__grouped_columns) }} )
        WITH

        all_lines as (
            SELECT *
            FROM {{ POST_PAY_LINES }}
            WHERE payer_code = '{{ payer_code }}'
        ),

        bridge AS (
            SELECT *
            FROM {{ BDG_CLAIM_SEGMENT_LINE }}
            WHERE payer_code = '{{ payer_code }}'
        ),

        line_status AS (
            SELECT
                segments.segment_key,
                segments.claim_number,
                {% for status in payment_statuses %}
                    substring(line.claim_line_status, 1, 1) = '{{ status.flag }}' as is_{{ status.name }}
                    {% if not loop.last%},{% endif %}
                {% endfor %}
            FROM bridge segments
            -- Optimized join using claim_number dist key
            INNER JOIN all_lines line ON
                segments.claim_number = line.claim_number AND
                segments.post_pay_line_key = line.post_pay_line_key
        ),

        segment AS (
            SELECT
                -- Optimized group by using claim_number dist key
                claim_number,
                segment_key,
                {% for status in payment_statuses %}
                    bool_and(
                        is_{{ status.name }}
                    ) as is_fully_{{ status.name }}
                    {% if not loop.last%},{% endif %}
                {% endfor %}
            FROM line_status
            GROUP BY 1, 2
        ),

        final as (
            select
                '{{ payer_code }}'::VARCHAR AS payer_code,
                segment_key,
                claim_number,

                CASE
                {% for status in payment_statuses %}
                        WHEN is_fully_{{ status.name }} THEN '{{ status.name | title }}'
                {% endfor %}
                ELSE 'Partial' END AS segment_status
            from segment
        )

        SELECT {{ generate_column_list_select(post_pay_payment_status__segment__grouped_columns) }} FROM final
    {% endset %}

    {{ print("Updating " ~ destination_table ~ " with " ~ payer_code ~ "'s data...") }}
    {% do run_query(query) %}
    {{ print("Updated " ~ destination_table ~ " with " ~ payer_code ~ "'s data.") }}
{% endmacro %}

