macro.concert.post_pay_procedure__claim_.macro_sql:
{% macro post_pay_procedure__claim__grouped(payer_code) %}
    {% set scopes = var('procedure_scopes') %}
    {% set max_service_units = (65535 / 6) | int %}

    {% set LINE_PROCEDURE = source('post_pay_staging', 'line_procedure') %}
    {% set destination_table = source('dw_common', 'post_pay_procedure__claim__grouped') %}

    {% set query %}
        DELETE FROM {{ destination_table }}
        WHERE payer_code = '{{ payer_code }}';

        INSERT INTO {{ destination_table }}
        ( {{ generate_column_list_insert(post_pay_procedure__claim__grouped_columns) }} )
        with

        -- Group by distinct claim and procedure
        claim_procedure as (
          select
            claim_number,
            procedure_code,

            any_value(clean_procedure_description) as procedure_description,
            -- Total service units
            sum(service_units)::int as service_units,
            -- Total service units for paid lines
            sum(
              case when is_paid = true
                then service_units
                else 0
              end
            )::int as paid_service_units,
            {% call(scope) for_delimited(scopes, ',') %}
              any_value(is_{{ scope }}) as is_{{ scope }},
              sum(
                case when is_{{ scope }} = true
                  then service_units
                  else 0
                end
              )::int as {{ scope }}_service_units,
              sum(
                case when is_{{ scope }} = true and is_paid = true
                  then service_units
                  else 0
                end
              )::int as paid_{{ scope }}_service_units
            {% endcall %}
          from {{ LINE_PROCEDURE }}
          WHERE payer_code = '{{ payer_code }}'
          group by 1, 2
        ),

        all_procedures_service_units as (
          select
            claim_number,
            procedure_code,
            service_units,
            {% for scope in scopes %}
              is_{{ scope }},
            {% endfor %}
            sum(service_units) over (
              partition by claim_number
            ) as claim_service_units
          from claim_procedure
        ),

        all_procedures_compatible as (
          select
              claim_number,
              procedure_code,
              service_units,
              {% call(scope) for_delimited(scopes, ',') %}
                is_{{ scope }}
              {% endcall %}
          from all_procedures_service_units
          where claim_service_units between 0 and {{ max_service_units }}
        ),

        all_procedures_values as (
          select
            claim_number,

            trim(
              listagg(
                repeat(
                  coalesce(procedure_code, '') || ' ',
                  service_units
                )
              ) within group (
                order by procedure_code
              )
            ) as all_procedures,

            {% call(scope) for_delimited(scopes, ',') %}
              trim(
                listagg(
                  case when is_{{ scope }} = true
                    then repeat(
                      coalesce(procedure_code, '') || ' ',
                      service_units
                    )
                    else null
                  end
                ) within group (
                  order by procedure_code
                )
              ) as all_{{ scope }}_procedures
            {% endcall %}
          from all_procedures_compatible
          group by 1
        ),


        final as (
          select
            '{{ payer_code }}' AS payer_code,
            claim_procedure.claim_number,

            {% for scope in [none] + scopes %}
              {% set scope_prefix = (scope ~ '_') if scope is not none else '' %}

              {% for paid in [none, 'paid'] %}
                {% set paid_prefix = (paid ~ '_') if paid is not none else '' %}

                {% set prefix = (paid_prefix ~ scope_prefix) %}

                -- Service Units
                sum(claim_procedure.{{ prefix }}service_units) as {{ prefix }}service_units,
                -- Procedure Signature
                listagg(
                  claim_procedure.procedure_code
                    || 'x'
                    || nullif(claim_procedure.{{ prefix }}service_units, 0),
                  ' '
                ) within group (
                  order by claim_procedure.procedure_code
                ) as {{ prefix }}procedure_signature,
              {% endfor %}

              any_value(all_procedures_values.all_{{ scope_prefix }}procedures) as all_{{ scope_prefix }}procedures,
            {% endfor %}

            listagg(
              claim_procedure.procedure_code
                || ': '
                || claim_procedure.procedure_description,
              ' | '
            ) as procedure_descriptions
          from claim_procedure
          left join all_procedures_values
            on claim_procedure.claim_number = all_procedures_values.claim_number
          group by 1, 2
        )

        SELECT {{ generate_column_list_select(post_pay_procedure__claim__grouped_columns) }} FROM final
    {% endset %}

    {{ print("Updating " ~ destination_table ~ " with " ~ payer_code ~ "'s data...") }}
    {% do run_query(query) %}
    {{ print("Updated " ~ destination_table ~ " with " ~ payer_code ~ "'s data.") }}
{% endmacro %}

