{% macro post_pay_diagnosis__segment__grouped(payer_code) %}
  -- Model Dependencies
  {% set DIM_DIAGNOSIS = ref('dim_diagnosis') %}
  {% set BDG_CLAIM_SEGMENT_LINE = source('post_pay_staging', 'bdg_claim_segment_line') %}
  {% set destination_table = source('dw_common', 'post_pay_diagnosis__segment__grouped') %}

  {% set query %}
        DELETE FROM {{ destination_table }}
        WHERE payer_code = '{{ payer_code }}';

        INSERT INTO {{ destination_table }}
        ( {{ generate_column_list_insert(post_pay_diagnosis__segment__grouped_columns) }} )
        WITH

        bridge AS (
            SELECT *
            FROM {{ BDG_CLAIM_SEGMENT_LINE }}
            WHERE payer_code = '{{ payer_code }}'
        ),

        all_lines AS (
            SELECT *
            FROM {{ source('post_pay_sources', 'post_pay_payers_claims_lines') }}
            WHERE payer_code = '{{ payer_code }}'
        ),

        flattened_line_diagnosis as (
          {% call(i) for_delimited(range(1, 11), 'union') %}
            SELECT
              segment.segment_key,
              segment.claim_number,
              line.diagnosis_code_{{ i }} AS diagnosis_code
            FROM bridge segment
            -- Optimized join using claim_number dist key
            INNER JOIN all_lines line ON
              segment.claim_number = line.claim_number AND
              segment.post_pay_line_key = line.post_pay_line_key
          {% endcall %}
        ),

        line_diagnosis as (
          SELECT
            flattened_line_diagnosis.segment_key,
            flattened_line_diagnosis.claim_number,
            flattened_line_diagnosis.diagnosis_code,
            COALESCE(diagnosis.diagnosis_description, 'Unknown') AS diagnosis_description
          FROM flattened_line_diagnosis
          LEFT JOIN {{ DIM_DIAGNOSIS }} diagnosis
            ON flattened_line_diagnosis.diagnosis_code = diagnosis.diagnosis_code
        ),

        final AS (
          SELECT
            -- Optimized group by using claim_number dist key
            '{{ payer_code }}' AS payer_code,
            claim_number,
            segment_key,

            -- All unique diagnosis codes seperated by a space
            listagg(
              nullif(diagnosis_code, 'Unspecified'),
              ' '
            ) within group (
              order by diagnosis_code
            ) as diagnosis_signature,
            -- All unique diagnosis descriptions
            listagg(
              nullif(diagnosis_code, 'Unspecified') || ': ' || diagnosis_description,
              ' | '
            ) within group (
              order by diagnosis_code
            ) as diagnosis_descriptions
          FROM line_diagnosis
          GROUP BY 1, 2, 3
        )

        SELECT {{ generate_column_list_select(post_pay_diagnosis__segment__grouped_columns) }} FROM final
  {% endset %}

  {{ print("Updating " ~ destination_table ~ " with " ~ payer_code ~ "'s data...") }}
  {% do run_query(query) %}
  {{ print("Updated " ~ destination_table ~ " with " ~ payer_code ~ "'s data.") }}
{% endmacro %}

