macro.concert.pre_segmentation_formattin.macro_sql:
{% macro pre_segmentation_formatting(payer_code) %}
  {% set provider_types = var('provider_types') %}
  {% set destination_table = source('post_pay_staging', 'pre_segmentation_formatting') %}


  {% set query %}
      DELETE FROM {{ destination_table }}
      WHERE payer_code = '{{ payer_code }}';

      INSERT INTO {{ destination_table }}
      ( {{ generate_column_list_insert(pre_segmentation_formatting_columns) }} )
      WITH

      line AS (
        SELECT *
        FROM {{ source('post_pay_sources', 'post_pay_payers_claims_lines') }}
        WHERE payer_code = '{{ payer_code }}'
      ),

      minimal_claim AS (
        SELECT
          claim_number,
          ANY_VALUE(payer_code)                                              AS payer_code,
          ANY_VALUE(cms_place_of_service_code)                               AS place_of_service,
          ANY_VALUE(type_of_bill)                                            AS type_of_bill,
          ANY_VALUE(admission_type)                                          AS admission_type,
          {{ post_pay_line_attr_concat("COALESCE(line.billed_amount, 0)") }} AS all_billed_amount,
          {{ post_pay_line_attr_concat("line.revenue_code") }}               AS all_revenue_code,
          {{ post_pay_line_attr_concat("line.procedure_code") }}             AS all_procedure_code,
          {{ post_pay_line_attr_concat("line.service_units") }}              AS all_service_units,
          {% call(i) for_delimited(range(1, 11), ',') %}
            {{ post_pay_line_attr_concat("line.diagnosis_code_" ~ i) }}      AS all_icd_code_{{ i }}
          {% endcall %},
          {% call(provider_type) for_delimited(provider_types, ',') %}
            {% set label = 'rendering' if provider_type == 'service' else provider_type %}
              ANY_VALUE(line.{{ provider_type }}_provider_ein) AS {{ label }}_provider_ein,
              ANY_VALUE(line.{{ provider_type }}_provider_npi) AS {{ label }}_provider_npi
          {% endcall %}
        FROM line
        GROUP BY 1

      ),

      final AS (
          SELECT
              payer_code,
              claim_number,

              {% call(provider_type) for_delimited(provider_types, ',') %}
                {% set label = 'rendering' if provider_type == 'service' else provider_type %}
                  minimal_claim.{{ label }}_provider_ein AS {{ label }}_provider_ein,
                  minimal_claim.{{ label }}_provider_npi AS {{ label }}_provider_npi
              {% endcall %},
              minimal_claim.place_of_service,
              minimal_claim.type_of_bill,
              minimal_claim.admission_type,
              minimal_claim.all_billed_amount,
              minimal_claim.all_revenue_code,
              minimal_claim.all_procedure_code,
              minimal_claim.all_service_units,
              {% call(i) for_delimited(range(1, 11), ',') %}
                  -- replaces the output of post_pay_line_attr_concat if that output isn't carrying any information
                  CASE
                      WHEN minimal_claim.all_icd_code_{{ i }} ~ '^[a-z0-9]{32}=[A-Z0-9]{1,}' THEN minimal_claim.all_icd_code_{{ i }}
                      ELSE ''
                  END AS all_icd_code_{{ i }}
              {% endcall %}
          FROM minimal_claim
      )

      SELECT {{ generate_column_list_select(pre_segmentation_formatting_columns) }} FROM final
  {% endset %}

  {{ print("Updating " ~ destination_table ~ " with " ~ payer_code ~ "'s data...") }}
  {% do run_query(query) %}
  {{ print("Updated " ~ destination_table ~ " with " ~ payer_code ~ "'s data.") }}

