  {% set BDG_HEALTH_PLAN_POLICY_CRITERIA_CLAIM_EDIT = ref('bdg_health_plan_policy_criteria_claim_edit') %}
  {% set DIM_CRITERIA = ref('dim_criteria') %}
  {% set destination_table = source('post_pay_staging', 'top_ranked_edit') %}

  -- Vars
  {% set NA_CLAIM_EDIT_KEY = generate_local_surrogate_key(['Not Applicable', '1']) %}
  {% set amount_types = var('amount_types') %}

  -- Queries
  {% set EDIT_TRACE = "COALESCE(line_edit.edit_trace, 'Not Applicable')" %}
  {% set IS_DENIED = "claim_edit.claim_edit_short_disposition = 'deny'" %}

  {% set query %}
      DELETE FROM {{ destination_table }}
      WHERE payer_code = '{{ payer_code }}';

      INSERT INTO {{ destination_table }}
      ( {{ generate_column_list_insert(top_ranked_edit_columns) }} )
      with

      all_lines AS (
        SELECT *
        FROM {{ source('post_pay_sources', 'post_pay_payers_claims_lines') }}
        WHERE payer_code = '{{ payer_code }}'
      ),

      facts as (
        select
          line.payer_code,
          line.claim_number,
          line.post_pay_line_key,
          coalesce(
            line_edit.claim_edit_key,
            {{ NA_CLAIM_EDIT_KEY }}
          ) as claim_edit_key,
          {{ EDIT_TRACE }} as edit_trace,
          md5({{ EDIT_TRACE }}) as edit_trace_hash,
          {% for amount_type in amount_types %}
              {% set label = 'paid' if amount_type == 'insurance_paid' else amount_type %}
              CASE
                  WHEN {{ IS_DENIED }} THEN line.{{ amount_type }}_amount
                  ELSE 0
              END AS edited_{{ label }}_amount,
          {% endfor %}
          line_edit.customer_code
        FROM all_lines line
        LEFT JOIN {{ LINE_EDIT }} line_edit ON
          line.post_pay_line_key = line_edit.post_pay_line_key AND
          line_edit.edit_rank = 1
        LEFT JOIN {{ DIM_CLAIM_EDIT }} claim_edit
          ON line_edit.claim_edit_key = claim_edit.claim_edit_key
      ),

      policy_criteria_dimensions AS (
        SELECT
          facts.*,
          COALESCE(policy_criteria_dimensions.policy_code     , 'Unknown') AS policy_code,
          COALESCE(policy_criteria_dimensions.policy_version  , 'Unknown') AS policy_version,
          COALESCE(policy_criteria_dimensions.policy_name     , 'Unknown') AS policy_name,
          COALESCE(policy_criteria_dimensions.criteria_code   , 'Unknown') AS criteria_code,
          COALESCE(policy_criteria_dimensions.criteria_version, 'Unknown') AS criteria_version,
          COALESCE(policy_criteria_dimensions.criteria_name   , 'Unknown') AS criteria_name,
          -- Ensure uniqueness of one edit per line
          ROW_NUMBER() OVER (
            PARTITION BY
              facts.post_pay_line_key,
              facts.claim_edit_key
            ORDER BY
              policy_criteria_dimensions.policy_version DESC
          )                                                                AS distinct_num
        FROM facts
        LEFT JOIN {{ BDG_HEALTH_PLAN_POLICY_CRITERIA_CLAIM_EDIT }} bridge
          ON bridge.claim_edit_key = facts.claim_edit_key
          AND bridge.health_plan_code =
            CASE
                WHEN facts.claim_edit_key = {{ NA_CLAIM_EDIT_KEY }} THEN 'Not Applicable'
                ELSE facts.customer_code
            END
          AND bridge.criteria_rank = 1
        LEFT JOIN {{ DIM_CRITERIA }} policy_criteria_dimensions
          ON bridge.policy_id = policy_criteria_dimensions.policy_id
          AND bridge.criteria_id = policy_criteria_dimensions.criteria_id
      )

      SELECT
        {{ generate_column_list_select(top_ranked_edit_columns) }}
      FROM policy_criteria_dimensions
      WHERE distinct_num = 1
  {% endset %}

  {{ print("Updating " ~ destination_table ~ " with " ~ payer_code ~ "'s data...") }}
  {% do run_query(query) %}
  {{ print("Updated " ~ destination_table ~ " with " ~ payer_code ~ "'s data.") }}
{% endmacro %}

macro.concert.post_pay_diagnosis__claim_.macro_sql:
{% macro post_pay_diagnosis__claim__grouped(payer_code) %}
  -- Model Dependencies
  {% set DIM_DIAGNOSIS = ref('dim_diagnosis') %}
  {% set POST_PAY_LINE = source('post_pay_sources', 'post_pay_payers_claims_lines') %}
  {% set destination_table = source('post_pay_staging', 'post_pay_diagnosis__claim__grouped') %}

  {% set query %}
      DELETE FROM {{ destination_table }}
      WHERE payer_code = '{{ payer_code }}';

      INSERT INTO {{ destination_table }}
      ( {{ generate_column_list_insert(post_pay_diagnosis__claim__grouped_columns) }})
      with

      line as (
        SELECT *
        FROM {{ POST_PAY_LINE }}
        WHERE payer_code = '{{ payer_code }}'
      ),

      flattened_line_diagnosis as (
        {% call(i) for_delimited(range(1, 11), 'union') %}
          select
            claim_number,
            diagnosis_code_{{ i }} AS diagnosis_code
          from line
        {% endcall %}
      ),

      line_diagnosis as (
        select
          flattened_line_diagnosis.claim_number,
          flattened_line_diagnosis.diagnosis_code,
          COALESCE(diagnosis.diagnosis_description, 'Unknown') AS diagnosis_description
        from flattened_line_diagnosis
        left join {{ DIM_DIAGNOSIS }} diagnosis
          on flattened_line_diagnosis.diagnosis_code = diagnosis.diagnosis_code
      ),

      final as (
        select
          '{{ payer_code }}' AS payer_code,
          claim_number,

          -- All unique diagnosis codes seperated by a space
          listagg(
            nullif(diagnosis_code, 'Unspecified'),
            ' '
          ) within group (
            order by diagnosis_code
          ) as diagnosis_signature,
          -- All unique diagnosis descriptions
          listagg(
            nullif(diagnosis_code, 'Unspecified') || ': ' || diagnosis_description,
            ' | '
          ) within group (
            order by diagnosis_code
          ) as diagnosis_descriptions
        from line_diagnosis
        group by 1, 2
      )

      SELECT {{ generate_column_list_select(post_pay_diagnosis__claim__grouped_columns) }} from final
  {% endset %}

  {{ print("Updating " ~ destination_table ~ " with " ~ payer_code ~ "'s data...") }}
  {% do run_query(query) %}
  {{ print("Updated " ~ destination_table ~ " with " ~ payer_code ~ "'s data.") }}
{% endmacro %}

macro.concert.post_pay_procedure__segmen.macro_sql:
{% macro post_pay_procedure__segment__grouped(payer_code, next = false) %}
  {% set next_prefix = '' if not next else 'next_' %}
  {% set table_prefix = 'latest_' if not next else 'next_' %}
  {% set scopes = var('procedure_scopes') %}
  {% set max_service_units = (65535 / 6) | int %}

  -- Model Dependencies
  {% set LINE_PROCEDURE = source('post_pay_staging', 'line_procedure') %}
  {% set POST_PAY_LINE = source('post_pay_sources', 'post_pay_payers_claims_lines') %}
  {% set destination_table = source('post_pay_staging', table_prefix ~ 'post_pay_procedure__segment__grouped') %}

  {% set query %}
      DELETE FROM {{ destination_table }}
      WHERE payer_code = '{{ payer_code }}';

      INSERT INTO {{ destination_table }}
      ( {{ generate_column_list_insert(post_pay_procedure__segment__grouped_columns) }} )
      WITH

      -- Group by distinct segment_key and procedure
      segment_procedure AS (
          SELECT
              -- Optimized group by operation using claim_number dist key
              claim_number,
              {% if next %}
                -- Fallback to non next segment key if needed
                coalesce({{ next_prefix }}segment_key, segment_key) AS segment_key,
              {% else %}
                segment_key,
              {% endif %}
              procedure_code,

              ANY_VALUE(clean_procedure_description) AS procedure_description,
              -- Total service units
              SUM(service_units)::INT AS service_units,
              -- Total service units for paid lines
              SUM(
                  CASE WHEN is_paid = true 
                      THEN service_units
                      ELSE 0
                  END
              )::INT AS paid_service_units,
              {% call(scope) for_delimited(scopes, ',') %}
                  ANY_VALUE(is_{{ scope }}) AS is_{{ scope }},
                  -- Total service units for scoped procedure lines
                  SUM(
                      CASE WHEN is_{{ scope }} = true
                          THEN service_units
                          ELSE 0
                      END
                  )::INT AS {{ scope }}_service_units,
                  -- Total service units for paid and scoped procedure lines
                  SUM(
                      CASE WHEN is_{{ scope }} = TRUE AND is_paid = true
                          THEN service_units
                          ELSE 0
                      END
                  )::INT AS paid_{{ scope }}_service_units
              {% endcall %}
          from {{ LINE_PROCEDURE }}
          WHERE payer_code = '{{ payer_code }}'
          group by 1, 2, 3
      ),

      all_procedures_service_units as (
          SELECT
              claim_number,
              segment_key,
              procedure_code,
              service_units,
              {% for scope in scopes %}
                  is_{{ scope }},
              {% endfor %}
              SUM(service_units) OVER (
                  PARTITION BY segment_key
              ) AS segment_key_service_units
          from segment_procedure
      ),

      all_procedures_compatible as (
          SELECT
              claim_number,
              segment_key,
              procedure_code,
              service_units,
              {% call(scope) for_delimited(scopes, ',') %}
                  is_{{ scope }}
              {% endcall %}
          FROM all_procedures_service_units
          WHERE segment_key_service_units BETWEEN 0 AND {{ max_service_units }}
      ),

      all_procedures_values AS (
          SELECT
              -- Optimized group by using claim_number dist key
              claim_number,
              segment_key,

              TRIM(
                  LISTAGG(
                      REPEAT(
                          COALESCE(procedure_code, '') || ' ',
                          service_units
                      )
                  ) WITHIN GROUP (
                      ORDER BY procedure_code
                  )
              ) AS all_procedures,

              {% call(scope) for_delimited(scopes, ',') %}
                  TRIM(
                      LISTAGG(
                          CASE WHEN is_{{ scope }} = TRUE
                              THEN REPEAT(
                                  COALESCE(procedure_code, '') || ' ',
                                  service_units
                              )
                              ELSE NULL
                          END
                      ) WITHIN GROUP (
                          ORDER BY procedure_code
                      )   
                  ) AS all_{{ scope }}_procedures
              {% endcall %}
          FROM all_procedures_compatible
          GROUP BY 1, 2
      ),

      final AS (
          SELECT
              '{{ payer_code }}' AS payer_code,
              segment_procedure.claim_number,
              segment_procedure.segment_key,

              {% for scope in [none] + scopes %}
                  {% set scope_prefix = (scope ~ '_') if scope is not none else '' %}

                  {% for paid in [none, 'paid'] %}
                      {% set paid_prefix = (paid ~ '_') if paid is not none else '' %}

                      {% set prefix = (paid_prefix ~ scope_prefix) %}

                      -- Service Units
                      SUM(segment_procedure.{{ prefix }}service_units) AS {{ prefix }}service_units,
                      -- Procedure Signature
                      LISTAGG(
                          segment_procedure.procedure_code
                              || 'x'
                              || NULLIF(segment_procedure.{{ prefix }}service_units, 0),
                          ' '
                      ) WITHIN GROUP (
                          ORDER BY segment_procedure.procedure_code
                      ) AS {{ prefix }}procedure_signature,
                  {% endfor %}

                  any_value(all_procedures_values.all_{{ scope_prefix }}procedures) as all_{{ scope_prefix }}procedures,
              {% endfor %}

              listagg(
                  segment_procedure.procedure_code
                      || ': '
                      || segment_procedure.procedure_description,
                  ' | '
              ) as procedure_descriptions
          FROM segment_procedure
          -- Optimized join using claim_number dist key
          LEFT JOIN all_procedures_values ON
              segment_procedure.claim_number = all_procedures_values.claim_number AND
              segment_procedure.segment_key = all_procedures_values.segment_key
          GROUP BY 1, 2, 3
      )

      SELECT {{ generate_column_list_select(post_pay_procedure__segment__grouped_columns) }} FROM final
  {% endset %}

  {{ print("Updating " ~ destination_table ~ " with " ~ payer_code ~ "'s data...") }}
  {% do run_query(query) %}
  {{ print("Updated " ~ destination_table ~ " with " ~ payer_code ~ "'s data.") }}
{% endmacro %}

macro.concert.post_pay__line__match.macro_sql:
{% macro post_pay__line__match(payer_code, next = false) %}

  {% set next_prefix = '' if not next else 'next_' %}
  {% set table_prefix = 'latest_' if not next else 'next_' %}

  -- Production/Current Model Id
  {% set CLAIM_MATCHING_MODEL_ID = env_var('CLAIM_MATCHING_MODEL_ID') %}

  -- Baseline entrypoint
  {% set SEGMENT_PREDICTION = source('post_pay_staging', table_prefix ~ 'segment_predictions') %}
  -- Used for retrieving matching features (gender, age_band, etc.)
  {% set PRE_INFERENCE_FORMATTING = source('post_pay_staging', table_prefix ~ 'pre_inference_formatting') %}
  -- Used to expand segments into lines
  {% set BDG_CLAIM_SEGMENT_LINE = source('post_pay_staging', 'bdg_claim_segment_line') %}
  -- Used to retrieve line specific attributes (procedure code, diagnosis codes, etc.)
  {% set TRANSFORMED = source('post_pay_sources', 'post_pay_payers_claims_lines') %}

  {% set destination_table = source('post_pay_staging', table_prefix ~ 'post_pay__line__match') %}

  {% set query %}
      DELETE FROM {{ destination_table }}
      WHERE payer_code = '{{ payer_code }}';

      INSERT INTO {{ destination_table }}
      ( {{ generate_column_list_insert(post_pay__line__match_columns) }} )
      WITH 

      final AS (
          SELECT
            line.payer_code                AS payer_code,
            line.claim_number              AS claim_number,
            line.claim_line_number         AS claim_line_number,
            line.procedure_code            AS procedure_code,
            line.service_units             AS service_units,
            {% for i in range(1, 11) %}
              line.diagnosis_code_{{ i }}  AS diagnosis_code_{{ i }},
            {% endfor %}
            pre.gender                     AS patient_gender,
            pre.member_age_band            AS patient_age_band,
            pre.service_provider_lab_code  AS service_provider_lab_code,
            pre.all_cpt                    AS procedure_signature,
            pre.all_icd                    AS diagnosis_signature,
            pre.segment_version            AS segment_version,
            pre.segment_class              AS segment_class,
            pre.segment_name               AS segment_name,
            pre.target_count               AS target_count,
            pred.model_id                  AS claim_matching_model_id,
            pred.predicted_label           AS category_id,
            pred.probability               AS category_probability
          FROM {{ SEGMENT_PREDICTION }} pred
          INNER JOIN {{ PRE_INFERENCE_FORMATTING }} pre ON
            pred.claim_number = pre.claim_number AND
            pred.segment_key = pre.segment_key
          INNER JOIN {{ BDG_CLAIM_SEGMENT_LINE }} bdg ON
            pred.claim_number = bdg.claim_number AND
            {% if next %}
              pred.segment_key = coalesce(bdg.{{ next_prefix }}segment_key, bdg.segment_key)
            {% else %}
              pred.segment_key = bdg.segment_key
            {% endif %}
          INNER JOIN {{ TRANSFORMED }} line ON
            bdg.claim_number = line.claim_number AND
            bdg.post_pay_line_key = line.post_pay_line_key
          WHERE
            line.payer_code = '{{ payer_code }}' AND
            pred.model_id {{ '=' if not next else '!=' }} '{{ CLAIM_MATCHING_MODEL_ID }}'
      )

      SELECT {{ generate_column_list_select(post_pay__line__match_columns) }} FROM final
  {% endset %}

  {{ print("Updating " ~ destination_table ~ " with " ~ payer_code ~ "'s data...") }}
  {% do run_query(query) %}
  {{ print("Updated " ~ destination_table ~ " with " ~ payer_code ~ "'s data.") }}

{% endmacro %}

