macro.concert.line_procedure.macro_sql:
{% macro line_procedure(payer_code) %}  
  {% set default_row_keys = var('default_row_keys') %}
  {% set scopes = var('procedure_scopes') %}

  -- Model Dependencies
  {% set POST_PAY_LINE = source('post_pay_sources', 'post_pay_payers_claims_lines') %}
  {% set BDG_CLAIM_SEGMENT_LINE = source('post_pay_staging', 'bdg_claim_segment_line') %}
  {% set DIM_PROCEDURE = ref('dim_procedure') %}
  {% set destination_table = source('post_pay_staging', 'line_procedure') %}

  {% set query %}
      DELETE FROM {{ destination_table }}
      WHERE payer_code = '{{ payer_code }}';

      INSERT INTO {{ destination_table }}
      ( {{ generate_column_list_insert(line_procedure_columns) }} ) 
      WITH
      final AS (
          SELECT 
              line.payer_code,
              segment.claim_number,
              segment.segment_key,
              segment.next_segment_key,
              line.post_pay_line_key,
              line.service_units,
              substring(line.claim_line_status, 1, 1) = 'P' as is_paid,
              case when dim_procedure.procedure_code in (
                      NULL,
                      {% call(row_key) for_delimited(default_row_keys, ',') %}
                          '{{ row_key }}'
                      {% endcall %}
                  )
                      then null
                  else dim_procedure.procedure_code
              end as procedure_code,
              dim_procedure.clean_procedure_description,
              {% call(scope) for_delimited(scopes, ',') %}
                  coalesce(dim_procedure.is_{{ scope }}, false) as is_{{ scope }}
              {% endcall %}
          FROM {{ BDG_CLAIM_SEGMENT_LINE }} segment
          -- Optimized join using claim_number dist key
          INNER JOIN {{ POST_PAY_LINE }} line ON
              segment.claim_number = line.claim_number AND
              segment.post_pay_line_key = line.post_pay_line_key
          INNER JOIN {{ DIM_PROCEDURE }} dim_procedure
              ON line.procedure_code = dim_procedure.procedure_code
          WHERE line.payer_code = '{{ payer_code }}'
      )

      SELECT {{ generate_column_list_select(line_procedure_columns) }} FROM final
  {% endset %}

  {{ print("Updating " ~ destination_table ~ " with " ~ payer_code ~ "'s data...") }}
  {% do run_query(query) %}
  {{ print("Updated " ~ destination_table ~ " with " ~ payer_code ~ "'s data.") }}
{% endmacro %}

macro.concert.segment_predictions.macro_sql:
{% macro segment_predictions(payer_code, next = false) %}
  {% set table_prefix = 'latest_' if not next else 'next_' %}

  -- Model Dependencies
  {% set MATCHING_CACHE = source('matching_cache', 'matching_cache') %}
  {% set PRE_INFERENCE_FORMATTING = source('post_pay_staging', table_prefix ~ 'pre_inference_formatting') %}
  {% set destination_table = source('post_pay_staging', table_prefix ~ 'segment_predictions') %}

  {% set query %}
      DELETE FROM {{ destination_table }}
      WHERE payer_code = '{{ payer_code }}';

      INSERT INTO {{ destination_table }}
      ( {{ generate_column_list_insert(segment_predictions_columns) }} )

      WITH

      final AS (
          SELECT 
              segments.payer_code,
              segments.segment_key,
              segments.claim_number,
              -- predictions
              segment_group_predictions.predicted_label,
              segment_group_predictions.probability,
              -- prediction metadata
              segment_group_predictions.model_id,
              -- duplicates handling
              ROW_NUMBER() OVER (
                  PARTITION BY 
                      segments.payer_code,
                      segments.segment_key,
                      segment_group_predictions.model_id
                  ORDER BY 
                      segment_group_predictions.probability DESC,
                      segments.segment_key DESC
              ) AS row_num
          FROM {{ PRE_INFERENCE_FORMATTING }} segments
          LEFT JOIN {{ MATCHING_CACHE }} segment_group_predictions
              -- join on all model inputs
              ON segments.all_cpt                   = segment_group_predictions.all_cpt                   AND
                 segments.all_icd                   = segment_group_predictions.all_icd                   AND
                 segments.gender                    = segment_group_predictions.gender                    AND
                 segments.member_age_band           = segment_group_predictions.member_age_band           AND
                 segments.service_provider_lab_code = segment_group_predictions.service_provider_lab_code AND
                 segments.segment_name              = segment_group_predictions.segment_name              AND
                 segments.segment_class             = segment_group_predictions.segment_class             AND
                 segments.target_count              = segment_group_predictions.target_count
          WHERE
              segments.payer_code = '{{ payer_code }}'
      )

      SELECT {{ generate_column_list_select(segment_predictions_columns) }} FROM final
      WHERE row_num = 1
  {% endset %}

  {{ print("Updating " ~ destination_table ~ " with " ~ payer_code ~ "'s data...") }}
  {% do run_query(query) %}
  {{ print("Updated " ~ destination_table ~ " with " ~ payer_code ~ "'s data.") }}

{% endmacro %}

