macro.concert.pre_inference_formatting.macro_sql:
{% macro pre_inference_formatting(payer_code, next = false) %}
  {% set next_prefix = '' if not next else 'next_' %}
  {% set table_prefix = 'latest_' if not next else 'next_' %}

  -- Model Dependencies
  {% set POST_SEGMENTATION_UNNESTING = source('post_pay_staging', 'post_segmentation_unnesting') %}
  {% set POST_PAY_DIAGNOSIS__CLAIM__GROUPED = source('post_pay_staging', 'post_pay_diagnosis__claim__grouped') %}
  {% set POST_PAY_PROCEDURE__SEGMENT__GROUPED = source('post_pay_staging', table_prefix ~ 'post_pay_procedure__segment__grouped') %}
  {% set destination_table = source('post_pay_staging', table_prefix ~ 'pre_inference_formatting') %}

  {% set query %}
      DELETE FROM {{ destination_table }}
      WHERE payer_code = '{{ payer_code }}';

      INSERT INTO {{ destination_table }}
      ( {{ generate_column_list_insert(pre_inference_formatting_columns) }} )
      WITH 

      segment AS (
          SELECT
            claim_number,
            post_pay_line_key,
            lab_code,
            -- When next is active, each of these columns should attempt to pull
            -- the 'next_' prefixed column, but fallback to the normal column name
            -- in the case where next segment rules are not set
            {% call(col) for_delimited([
                'segment_key',
                'segment_version',
                'segment_name',
                'segment_class',
                'target_count',
            ], ',') %}
                {% if next %}
                    coalesce({{ next_prefix }}{{ col }}, {{ col }}) AS {{ col }}
                {% else %}
                    {{ col }}
                {% endif %}
            {% endcall %}
          FROM {{ POST_SEGMENTATION_UNNESTING }}
          WHERE payer_code = '{{ payer_code }}'
      ),

      line AS (
          SELECT * 
          FROM {{ source('post_pay_sources', 'post_pay_payers_claims_lines') }}
          WHERE payer_code = '{{ payer_code }}'
      ),


      -- NOTE( 2024-04-09 ): This table being at the Claim Grain instead of the
      -- Segment Grain is NOT a mistake:
      --    - (all_icd needs to be aggregated at the Claim grain instead of the Segment Grain (even though prediction DOES happen at the Segment Grain))
      diagnosis AS (
          SELECT 
            claim_number,
            diagnosis_signature 
          FROM {{ POST_PAY_DIAGNOSIS__CLAIM__GROUPED }}
          WHERE payer_code = '{{ payer_code }}'
      ),

      procedure AS (
          SELECT
            claim_number,
            segment_key,
            all_procedures
          FROM {{ POST_PAY_PROCEDURE__SEGMENT__GROUPED }}
          WHERE payer_code = '{{ payer_code }}'
      ),

      segments AS (
          SELECT
              -- Optimized group by using claim_number dist key
              line.payer_code                                                   AS  payer_code,
              segment.claim_number                                              AS  claim_number,
              segment.segment_key                                               AS  segment_key,

              COALESCE(ANY_VALUE(procedure.all_procedures), '')                 AS  all_cpt,
              COALESCE(ANY_VALUE(diagnosis.diagnosis_signature), '')            AS  all_icd,
              ANY_VALUE(
                  CASE line.member_sex
                      WHEN 'Male' THEN 'M'
                      WHEN 'Female' THEN 'F'
                      ELSE 'X'
                  END
              )                                                                 AS  gender,
              COALESCE(ANY_VALUE(line.member_age), 35)                          AS  member_age_band,
              ANY_VALUE(REPLACE(segment.lab_code, 'Unknown', 'OtherProvider'))  AS  service_provider_lab_code,
              ANY_VALUE(segment.segment_version)                                AS  segment_version,
              ANY_VALUE(segment.segment_name)                                   AS  segment_name,
              ANY_VALUE(segment.segment_class)                                  AS  segment_class,
              ANY_VALUE(segment.target_count)                                   AS  target_count
          FROM segment
          -- Optimized join using claim_number dist key
          INNER JOIN line ON
              segment.claim_number = line.claim_number AND
              segment.post_pay_line_key = line.post_pay_line_key
          -- Optimized join using claim_number dist key
          LEFT JOIN procedure ON
              segment.claim_number = procedure.claim_number AND
              segment.segment_key = procedure.segment_key
          LEFT JOIN diagnosis
              ON segment.claim_number = diagnosis.claim_number
          GROUP BY 1, 2, 3
      )

      SELECT {{ generate_column_list_select(pre_inference_formatting_columns) }} FROM segments
  {% endset %}

  {{ print("Updating " ~ destination_table ~ " with " ~ payer_code ~ "'s data...") }}
  {% do run_query(query) %}
  {{ print("Updated " ~ destination_table ~ " with " ~ payer_code ~ "'s data.") }}
{% endmacro %}

