macro.concert.to_json_string.macro_sql:
{% macro to_json_string(definition_dict) %}
    (
        '{' || {{ '' }}
        {%- for key, value in definition_dict.items() -%}
            {%- set hasLiteral = 'literal' in value and value.literal is not none -%}
            {%- set hasSql = 'sql' in value and value.sql is not none -%}
            {%- set isQuoted = 'quoted' not in value or value.quoted -%}
            {# key #}
            '{{ "," if not loop.first else "" }}"{{ key }}":' ||
            {%- if hasLiteral -%}
                {# optional literal value #}
                '{{ '"' if isQuoted else '' }}{{ value.literal }}{{ '"' if isQuoted else '' }}' ||
            {%- elif hasSql -%}
                {# optional sql value #}
                coalesce(
                    {{ '(\'"\' || ' if isQuoted else '' -}}
                    {{- value.sql -}}::varchar
                    {{- ' || \'"\')' if isQuoted else '' }}
                    , 'null'
                ) ||
            {%- else -%}
                {# If literal and sql values are both either missing or none then just send null #}
                'null' ||
            {%- endif -%}
        {%- endfor -%}
        {{ '' }} '}'
    )
{% endmacro %}

