macro.concert.add_claim_edit_api_traces_.macro_sql:
{% macro add_claim_edit_api_traces_partitions_for_year(start_year, start_month, start_day) %}

  {% set start_date = modules.datetime.date(start_year | int, start_month | int, start_day | int) %}
  {% set one_day = modules.datetime.timedelta(days=1) %}
  {% set batch_size = 100 %}
  {% set total_days = 365 %}

  {% for batch_start in range(0, total_days, batch_size) %}
    {% set batch_end = [batch_start + batch_size, total_days] | min %}

    {% set partition_clauses = [] %}
    {% for i in range(batch_start, batch_end) %}
      {% set current_date = start_date + (one_day * i) %}
      {% set year = current_date.strftime('%Y') %}
      {% set month = current_date.strftime('%m') %}
      {% set day = current_date.strftime('%d') %}
      {% do partition_clauses.append(
        "PARTITION (year='" ~ year ~ "', month='" ~ month ~ "', day='" ~ day ~ "') " ~
        "LOCATION 's3://claim-edit-api-traces/spans/year=" ~ year ~ "/month=" ~ month ~ "/day=" ~ day ~ "/'"
      ) %}
    {% endfor %}

    {% set query %}
      ALTER TABLE spectrum_schema.claim_edit_api_traces ADD IF NOT EXISTS
      {{ partition_clauses | join('\n') }};
    {% endset %}

    {% do run_query(query) %}
  {% endfor %}

{% endmacro %}

